// Turns SVG path data ("M12.8,14.2C14.2,14.2 ...") into an android.graphics.Path.
object SvgPath {
    private val token = Regex("[MmLlHhVvCcSsQqTtZzAa]|[-+]?(?:\\d*\\.\\d+|\\d+\\.?)(?:[eE][-+]?\\d+)?")
 
    fun parse(data: String): Path {
        val path = Path()
        val t = token.findAll(data).map { it.value }.toList()
        var i = 0
        var cmd = ' '
        var last = ' '
        var cx = 0f
        var cy = 0f
        var sx = 0f
        var sy = 0f
        var px = 0f // the last control point, for S and T
        var py = 0f
        fun num(): Float = t[i++].toFloat()
        while (i < t.size) {
            val tk = t[i]
            if (tk[0].isLetter()) {
                cmd = tk[0]
                i++
                if (cmd == 'Z' || cmd == 'z') {
                    path.close()
                    cx = sx
                    cy = sy
                    last = cmd
                    continue
                }
            }
            val rel = cmd.isLowerCase()
            when (cmd.uppercaseChar()) {
                'M' -> {
                    val x = num() + (if (rel) cx else 0f)
                    val y = num() + (if (rel) cy else 0f)
                    path.moveTo(x, y)
                    cx = x
                    cy = y
                    sx = x
                    sy = y
                    cmd = if (rel) 'l' else 'L'
                }
                'L' -> {
                    val x = num() + (if (rel) cx else 0f)
                    val y = num() + (if (rel) cy else 0f)
                    path.lineTo(x, y)
                    cx = x
                    cy = y
                }
                'H' -> {
                    val x = num() + (if (rel) cx else 0f)
                    path.lineTo(x, cy)
                    cx = x
                }
                'V' -> {
                    val y = num() + (if (rel) cy else 0f)
                    path.lineTo(cx, y)
                    cy = y
                }
                'C' -> {
                    val ox = if (rel) cx else 0f
                    val oy = if (rel) cy else 0f
                    val x1 = num() + ox
                    val y1 = num() + oy
                    val x2 = num() + ox
                    val y2 = num() + oy
                    val x = num() + ox
                    val y = num() + oy
                    path.cubicTo(x1, y1, x2, y2, x, y)
                    px = x2
                    py = y2
                    cx = x
                    cy = y
                }
                'S' -> {
                    val ox = if (rel) cx else 0f
                    val oy = if (rel) cy else 0f
                    val smooth = last == 'C' || last == 'c' || last == 'S' || last == 's'
                    val x1 = if (smooth) 2 * cx - px else cx
                    val y1 = if (smooth) 2 * cy - py else cy
                    val x2 = num() + ox
                    val y2 = num() + oy
                    val x = num() + ox
                    val y = num() + oy
                    path.cubicTo(x1, y1, x2, y2, x, y)
                    px = x2
                    py = y2
                    cx = x
                    cy = y
                }
                'Q' -> {
                    val ox = if (rel) cx else 0f
                    val oy = if (rel) cy else 0f
                    val x1 = num() + ox
                    val y1 = num() + oy
                    val x = num() + ox
                    val y = num() + oy
                    path.quadTo(x1, y1, x, y)
                    px = x1
                    py = y1
                    cx = x
                    cy = y
                }
                'T' -> {
                    val smooth = last == 'Q' || last == 'q' || last == 'T' || last == 't'
                    val x1 = if (smooth) 2 * cx - px else cx
                    val y1 = if (smooth) 2 * cy - py else cy
                    val x = num() + (if (rel) cx else 0f)
                    val y = num() + (if (rel) cy else 0f)
                    path.quadTo(x1, y1, x, y)
                    px = x1
                    py = y1
                    cx = x
                    cy = y
                }
                'A' -> {
                    val rx = abs(num())
                    val ry = abs(num())
                    i++ // the rotation of the arc (the icons do not use it)
                    val large = num() != 0f
                    val sweep = num() != 0f
                    val x = num() + (if (rel) cx else 0f)
                    val y = num() + (if (rel) cy else 0f)
                    arcTo(path, cx, cy, rx, ry, large, sweep, x, y)
                    cx = x
                    cy = y
                }
                else -> i++
            }
            last = cmd
        }
        return path
    }
 
    // An SVG arc from (x0, y0) to (x, y), converted to Path.arcTo.
    private fun arcTo(
        path: Path,
        x0: Float,
        y0: Float,
        rxIn: Float,
        ryIn: Float,
        large: Boolean,
        sweep: Boolean,
        x: Float,
        y: Float,
    ) {
        if (rxIn == 0f || ryIn == 0f || (x0 == x && y0 == y)) {
            path.lineTo(x, y)
            return
        }
        var rx = rxIn.toDouble()
        var ry = ryIn.toDouble()
        val dx = (x0 - x) / 2.0
        val dy = (y0 - y) / 2.0
        val lambda = (dx * dx) / (rx * rx) + (dy * dy) / (ry * ry)
        if (lambda > 1.0) {
            val s = sqrt(lambda)
            rx *= s
            ry *= s
        }
        val rx2 = rx * rx
        val ry2 = ry * ry
        val top = rx2 * ry2 - rx2 * dy * dy - ry2 * dx * dx
        val bottom = rx2 * dy * dy + ry2 * dx * dx
        var coef = sqrt(max(0.0, top / bottom))
        if (large == sweep) coef = -coef
        val cxp = coef * (rx * dy / ry)
        val cyp = coef * (-(ry * dx) / rx)
        val cx = cxp + (x0 + x) / 2.0
        val cy = cyp + (y0 + y) / 2.0
        val theta1 = atan2((dy - cyp) / ry, (dx - cxp) / rx)
        val theta2 = atan2((-dy - cyp) / ry, (-dx - cxp) / rx)
        var delta = theta2 - theta1
        if (!sweep && delta > 0) delta -= 2 * PI
        if (sweep && delta < 0) delta += 2 * PI
        val box = RectF((cx - rx).toFloat(), (cy - ry).toFloat(), (cx + rx).toFloat(), (cy + ry).toFloat())
        path.arcTo(box, Math.toDegrees(theta1).toFloat(), Math.toDegrees(delta).toFloat())
    }
}
 
// Draws the original icons. Used by OfficialIconView and by views that draw by themselves.
object OfficialIconPainter {
    private val cache = HashMap<OfficialIcon, List<Path>>()
    private val paint = Paint(Paint.ANTI_ALIAS_FLAG)
 
    // Draws the icon in the square that starts at (left, top) and is size x size pixels, in the given color.
    fun draw(canvas: Canvas, icon: OfficialIcon, left: Float, top: Float, size: Float, tint: Int) {
        val paths = cache.getOrPut(icon) { icon.layers.map { SvgPath.parse(it.data) } }
        canvas.save()
        canvas.translate(left, top)
        val scale = size / icon.viewport
        canvas.scale(scale, scale)
        icon.layers.forEachIndexed { index, layer ->
            val path = paths[index]
            path.fillType = if (layer.evenOdd) Path.FillType.EVEN_ODD else Path.FillType.WINDING
            paint.color = tint
            if (layer.fill) {
                paint.style = Paint.Style.FILL
                canvas.drawPath(path, paint)
            }
            if (layer.strokeWidth > 0f) {
                paint.style = Paint.Style.STROKE
                paint.strokeWidth = layer.strokeWidth
                paint.strokeCap = if (layer.round) Paint.Cap.ROUND else Paint.Cap.BUTT
                paint.strokeJoin = if (layer.round) Paint.Join.ROUND else Paint.Join.MITER
                canvas.drawPath(path, paint)
            }
        }
        canvas.restore()
    }
}
 
// Draws one of the original icons in a given color. Works with setTint() like the other icon views.
class OfficialIconView(context: Context, private val icon: OfficialIcon, private var tint: Int) : View(context) {
    fun setTint(color: Int) {
        tint = color
        invalidate()
    }
 
    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)
        if (width <= 0 || height <= 0) return
        val size = min(width, height).toFloat()
        OfficialIconPainter.draw(canvas, icon, (width - size) / 2f, (height - size) / 2f, size, tint)
    }
}
 
